'use strict';

// MODULES //

var tape = require( 'tape' );
var constantFunction = require( '@stdlib/utils/constant-function' );
var Int32Array = require( '@stdlib/array/int32' );
var Float64Array = require( '@stdlib/array/float64' );
var Complex128Array = require( '@stdlib/array/complex128' );
var BooleanArray = require( '@stdlib/array/bool' );
var Complex128 = require( '@stdlib/complex/float64/ctor' );
var AccessorArray = require( '@stdlib/array/base/accessor' );
var isSameComplex128Array = require( '@stdlib/assert/is-same-complex128array' );
var isEqualBooleanArray = require( '@stdlib/assert/is-equal-booleanarray' );
var isArray = require( '@stdlib/assert/is-array' );
var isFloat64Array = require( '@stdlib/assert/is-float64array' );
var isInt32Array = require( '@stdlib/assert/is-int32array' );
var isComplex128Array = require( '@stdlib/assert/is-complex128array' );
var isBooleanArray = require( '@stdlib/assert/is-booleanarray' );
var toFilledBy = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof toFilledBy, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns a new array with all elements within a specified range replaced according to a provided callback function (generic)', function test( t ) {
	var expected;
	var actual;
	var x;

	x = [ 1, 2, 3, 4 ];

	expected = [ 5, 5, 5, 5 ];
	actual = toFilledBy( x, 0, x.length, constantFunction( 5 ) );

	t.notEqual( actual, x, 'returns different reference' );
	t.strictEqual( isArray( actual ), true, 'returns expected value' );
	t.deepEqual( actual, expected, 'returns expected value' );

	expected = [ 1, 5, 5, 4 ];
	actual = toFilledBy( x, 1, 3, constantFunction( 5 ) );

	t.notEqual( actual, x, 'returns different reference' );
	t.strictEqual( isArray( actual ), true, 'returns expected value' );
	t.deepEqual( actual, expected, 'returns expected value' );

	expected = [ 1, 6, 6, 4 ];
	actual = toFilledBy( x, -3, -1, constantFunction( 6 ) );

	t.notEqual( actual, x, 'returns different reference' );
	t.strictEqual( isArray( actual ), true, 'returns expected value' );
	t.deepEqual( actual, expected, 'returns expected value' );

	t.end();
});

