tape( 'the function clamps `start` and `end` indices to array bounds', function test( t ) {
	var expected;
	var actual;
	var x;

	x = [ 1, 2, 3, 4 ];

	expected = [ 5, 5, 5, 5 ];
	actual = toFilledBy( x, -10, 100, constantFunction( 5 ) );

	t.deepEqual( actual, expected, 'returns expected value' );

	expected = [ 1, 2, 3, 4 ];
	actual = toFilledBy( x, 10, 100, constantFunction( 5 ) );

	t.deepEqual( actual, expected, 'returns expected value' );

	expected = [ 1, 2, 3, 4 ];
	actual = toFilledBy( x, 0, -10, constantFunction( 5 ) );

	t.deepEqual( actual, expected, 'returns expected value' );

	expected = [ 1, 2, 3, 4 ];
	actual = toFilledBy( x, 2, 2, constantFunction( 5 ) );

	t.deepEqual( actual, expected, 'returns expected value' );

	t.end();
});

tape( 'the function returns an empty array if provided an array of length `0`', function test( t ) {
	var expected;
	var actual;

	expected = [];
	actual = toFilledBy( [], 0, 0, constantFunction( 5 ) );

	t.deepEqual( actual, expected, 'returns expected value' );
	t.end();
});

tape( 'the function invokes a callback function with three arguments', function test( t ) {
	var expected;
	var indices;
	var values;
	var arrays;
	var actual;
	var x;

	x = [ 1, 2, 3, 4 ];

	values = [];
	indices = [];
	arrays = [];
	actual = toFilledBy( x, 1, 3, fcn );

	t.notEqual( actual, x, 'returns different reference' );

	expected = [ 1, 20, 30, 4 ];
	t.deepEqual( actual, expected, 'returns expected value' );

	expected = [ 2, 3 ];
	t.deepEqual( values, expected, 'returns expected value' );

	expected = [ 1, 2 ];
	t.deepEqual( indices, expected, 'returns expected value' );

	expected = [ x, x ];
	t.deepEqual( arrays, expected, 'returns expected value' );

	t.end();

	function fcn( value, index, arr ) {
		values.push( value );
		indices.push( index );
		arrays.push( arr );
		return value * 10;
	}
});

tape( 'the function supports providing an execution context', function test( t ) {
	var expected;
	var actual;
	var ctx;
	var x;

	x = [ 1, 2, 3, 4 ];
	ctx = {
		'count': 0
	};

	actual = toFilledBy( x, 1, 3, fcn, ctx );

	t.notEqual( actual, x, 'returns different reference' );

	expected = [ 1, 20, 30, 4 ];
	t.deepEqual( actual, expected, 'returns expected value' );

	t.strictEqual( ctx.count, 2, 'returns expected value' );

	t.end();

	function fcn( value ) {
		this.count += 1; // eslint-disable-line no-invalid-this
		return value * 10;
	}
});
